//! Gives plex-couch.exe its icon (Explorer, Task Manager, the taskbar) without rc.exe or
//! build dependencies: assets/plex-couch.ico is turned into a compiled resource file
//! (`.res`: one RT_ICON per image plus RT_GROUP_ICON 1) and handed to the MSVC linker,
//! which accepts `.res` inputs directly. Other targets are left alone. The icon itself is
//! generated by `cargo run --example make_icon` (see src/icon.rs).

use std::path::PathBuf;

const ICO: &str = "assets/plex-couch.ico";
const RT_ICON: u16 = 3;
const RT_GROUP_ICON: u16 = 14;

fn u16_at(b: &[u8], i: usize) -> u16 {
    u16::from_le_bytes([b[i], b[i + 1]])
}

fn u32_at(b: &[u8], i: usize) -> u32 {
    u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]])
}

/// One `.res` entry with an ordinal type and name, padded to 4 bytes.
fn resource(out: &mut Vec<u8>, kind: u16, id: u16, flags: u16, data: &[u8]) {
    out.extend_from_slice(&(data.len() as u32).to_le_bytes()); // DataSize
    out.extend_from_slice(&32u32.to_le_bytes()); // HeaderSize
    out.extend_from_slice(&[0xFF, 0xFF]);
    out.extend_from_slice(&kind.to_le_bytes());
    out.extend_from_slice(&[0xFF, 0xFF]);
    out.extend_from_slice(&id.to_le_bytes());
    out.extend_from_slice(&0u32.to_le_bytes()); // DataVersion
    out.extend_from_slice(&flags.to_le_bytes()); // MemoryFlags
    out.extend_from_slice(&0x0409u16.to_le_bytes()); // LanguageId: en-US
    out.extend_from_slice(&0u32.to_le_bytes()); // Version
    out.extend_from_slice(&0u32.to_le_bytes()); // Characteristics
    out.extend_from_slice(data);
    while !out.len().is_multiple_of(4) {
        out.push(0);
    }
}

fn res_from_ico(ico: &[u8]) -> Vec<u8> {
    assert!(ico.len() >= 6 && u16_at(ico, 2) == 1, "{ICO} is not an icon file");
    let count = u16_at(ico, 4) as usize;
    // the empty resource every .res file starts with
    let mut out = vec![0, 0, 0, 0, 32, 0, 0, 0, 0xFF, 0xFF, 0, 0, 0xFF, 0xFF, 0, 0];
    out.resize(32, 0);
    let mut group = Vec::with_capacity(6 + 14 * count);
    group.extend_from_slice(&[0, 0, 1, 0]);
    group.extend_from_slice(&(count as u16).to_le_bytes());
    for n in 0..count {
        let e = 6 + 16 * n;
        let (len, off) = (u32_at(ico, e + 8) as usize, u32_at(ico, e + 12) as usize);
        let id = (n + 1) as u16;
        resource(&mut out, RT_ICON, id, 0x1010, &ico[off..off + len]);
        group.extend_from_slice(&ico[e..e + 12]); // width .. bytes in resource
        group.extend_from_slice(&id.to_le_bytes());
    }
    resource(&mut out, RT_GROUP_ICON, 1, 0x1030, &group);
    out
}

fn main() {
    println!("cargo:rerun-if-changed={ICO}");
    println!("cargo:rerun-if-changed=build.rs");
    let windows = std::env::var("CARGO_CFG_TARGET_OS").as_deref() == Ok("windows");
    let msvc = std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc");
    if !(windows && msvc) {
        return;
    }
    let ico = std::fs::read(ICO).expect("read the icon");
    let res = PathBuf::from(std::env::var("OUT_DIR").expect("OUT_DIR")).join("plex-couch.res");
    std::fs::write(&res, res_from_ico(&ico)).expect("write the .res");
    println!("cargo:rustc-link-arg-bin=plex-couch={}", res.display());
}
